import{A as e,E as t,R as n,d as r,f as i,l as a,p as o,s}from"./runtime-core.esm-bundler-tCF-J6l5.js";import{t as c}from"./app-D5IRkmio.js";var l=JSON.parse(`{"path":"/%E5%90%8E%E7%AB%AF%E5%BC%80%E5%8F%91/%E6%95%B0%E6%8D%AE%E5%BA%93/SQLServer/02_%E8%BF%9B%E9%98%B6%E7%AF%87/03_%E7%AA%97%E5%8F%A3%E5%87%BD%E6%95%B0.html","title":"窗口函数","lang":"zh-CN","frontmatter":{"title":"窗口函数","order":3,"category":["数据库","SQLServer"],"tag":["SQL Server","窗口函数","Window Function","数据分析","ROW_NUMBER"]},"git":{"createdTime":1780573763000,"updatedTime":1780573763000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":1}]},"readingTime":{"minutes":6.69,"words":2008},"filePathRelative":"后端开发/数据库/SQLServer/02_进阶篇/03_窗口函数.md"}`),u={name:`03_窗口函数.md`},d={class:`hint-container tip`};function f(c,l,u,f,p,m){let h=e(`RouteLink`),g=e(`Mermaid`);return t(),a(`div`,null,[l[7]||=s(`h1`,{id:`窗口函数`,tabindex:`-1`},[s(`a`,{class:`header-anchor`,href:`#窗口函数`},[s(`span`,null,`窗口函数`)])],-1),l[8]||=s(`blockquote`,null,[s(`p`,null,[s(`strong`,null,`窗口函数让 SQL 的表达能力跃升一个维度——既能看个体，又能看整体，互不干扰。`),i(` 这是 SQL 从"会用"到"精通"的分水岭。`)])],-1),s(`div`,d,[l[3]||=s(`p`,{class:`hint-container-title`},`与现有内容的关系`,-1),s(`p`,null,[l[1]||=i(`本篇聚焦 SQL Server 窗口函数的完整语法与性能优化。更深入的窗口函数实战练习，参考 `,-1),o(h,{to:`/%E5%90%8E%E7%AB%AF%E5%BC%80%E5%8F%91/ASP.NET_Core/SQL%20Server%E8%BF%9B%E9%98%B6/01.%E7%AA%97%E5%8F%A3%E5%87%BD%E6%95%B0%E7%B2%BE%E9%80%9A.html`},{default:n(()=>[...l[0]||=[i(`SQL Server 进阶 · 窗口函数精通`,-1)]]),_:1}),l[2]||=i(`。`,-1)])]),l[9]||=r(`<hr><h2 id="一、窗口函数-vs-group-by" tabindex="-1"><a class="header-anchor" href="#一、窗口函数-vs-group-by"><span>一、窗口函数 vs GROUP BY</span></a></h2><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- GROUP BY：压缩行，每个组一行</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> Department, </span><span style="color:#56B6C2;">AVG</span><span style="color:#ABB2BF;">(Salary) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> AvgSalary</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Employees</span></span>
<span class="line"><span style="color:#C678DD;">GROUP BY</span><span style="color:#ABB2BF;"> Department;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 结果：IT / 15000, HR / 12000</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 窗口函数：保留所有行，附加聚合值</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> EmployeeId, </span><span style="color:#C678DD;">Name</span><span style="color:#ABB2BF;">, Department, Salary,</span></span>
<span class="line"><span style="color:#56B6C2;">       AVG</span><span style="color:#ABB2BF;">(Salary) </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">PARTITION</span><span style="color:#C678DD;"> BY</span><span style="color:#ABB2BF;"> Department) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> DeptAvgSalary</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Employees;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 结果：每行都有部门平均工资，但原始行不丢失</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div>`,3),o(g,{code:``}),l[10]||=r(`<hr><h2 id="二、排序窗口函数" tabindex="-1"><a class="header-anchor" href="#二、排序窗口函数"><span>二、排序窗口函数</span></a></h2><h3 id="_2-1-row-number-rank-dense-rank-ntile" tabindex="-1"><a class="header-anchor" href="#_2-1-row-number-rank-dense-rank-ntile"><span>2.1 ROW_NUMBER / RANK / DENSE_RANK / NTILE</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 示例数据：同部门同薪水的情况</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- IT部: 张三=15000, 李四=15000, 王五=18000</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- HR部: 赵六=10000, 钱七=12000</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#C678DD;"> Name</span><span style="color:#ABB2BF;">, Department, Salary,</span></span>
<span class="line"><span style="color:#56B6C2;">    ROW_NUMBER</span><span style="color:#ABB2BF;">() </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">PARTITION</span><span style="color:#C678DD;"> BY</span><span style="color:#ABB2BF;"> Department </span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> Salary </span><span style="color:#C678DD;">DESC</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> rn,</span></span>
<span class="line"><span style="color:#56B6C2;">    RANK</span><span style="color:#ABB2BF;">()       </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">PARTITION</span><span style="color:#C678DD;"> BY</span><span style="color:#ABB2BF;"> Department </span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> Salary </span><span style="color:#C678DD;">DESC</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> rnk,</span></span>
<span class="line"><span style="color:#56B6C2;">    DENSE_RANK</span><span style="color:#ABB2BF;">() </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">PARTITION</span><span style="color:#C678DD;"> BY</span><span style="color:#ABB2BF;"> Department </span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> Salary </span><span style="color:#C678DD;">DESC</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> drnk,</span></span>
<span class="line"><span style="color:#56B6C2;">    NTILE</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">)     </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">PARTITION</span><span style="color:#C678DD;"> BY</span><span style="color:#ABB2BF;"> Department </span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> Salary </span><span style="color:#C678DD;">DESC</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> bucket</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Employees;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- IT 部结果：</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 王五 18000  rn=1  rnk=1  drnk=1  bucket=1</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 张三 15000  rn=2  rnk=2  drnk=2  bucket=1</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 李四 15000  rn=3  rnk=2  drnk=2  bucket=2  ← 注意差异</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- HR 部结果：</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 钱七 12000  rn=1  rnk=1  drnk=1  bucket=1</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 赵六 10000  rn=2  rnk=2  drnk=2  bucket=2</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><table><thead><tr><th>函数</th><th>相同值处理</th><th>示例（同值 15000）</th></tr></thead><tbody><tr><td><code>ROW_NUMBER</code></td><td>不同编号</td><td>1, 2, 3</td></tr><tr><td><code>RANK</code></td><td>同编号，跳号</td><td>1, 2, 2, 4</td></tr><tr><td><code>DENSE_RANK</code></td><td>同编号，不跳号</td><td>1, 2, 2, 3</td></tr><tr><td><code>NTILE(n)</code></td><td>分 n 组</td><td>1, 1, 2, 2</td></tr></tbody></table><hr><h2 id="三、聚合窗口函数" tabindex="-1"><a class="header-anchor" href="#三、聚合窗口函数"><span>三、聚合窗口函数</span></a></h2><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- SUM / COUNT / AVG / MIN / MAX OVER()</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span></span>
<span class="line"><span style="color:#ABB2BF;">    OrderId, CustomerId, OrderDate, Amount,</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    -- 累计金额（按日期排序）</span></span>
<span class="line"><span style="color:#56B6C2;">    SUM</span><span style="color:#ABB2BF;">(Amount) </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> OrderDate</span></span>
<span class="line"><span style="color:#C678DD;">        ROWS</span><span style="color:#C678DD;"> BETWEEN</span><span style="color:#C678DD;"> UNBOUNDED</span><span style="color:#C678DD;"> PRECEDING</span><span style="color:#C678DD;"> AND</span><span style="color:#ABB2BF;"> CURRENT </span><span style="color:#C678DD;">ROW</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> RunningTotal,</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    -- 部门内累计</span></span>
<span class="line"><span style="color:#56B6C2;">    SUM</span><span style="color:#ABB2BF;">(Amount) </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">PARTITION</span><span style="color:#C678DD;"> BY</span><span style="color:#ABB2BF;"> CustomerId </span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> OrderDate</span></span>
<span class="line"><span style="color:#C678DD;">        ROWS</span><span style="color:#C678DD;"> BETWEEN</span><span style="color:#C678DD;"> UNBOUNDED</span><span style="color:#C678DD;"> PRECEDING</span><span style="color:#C678DD;"> AND</span><span style="color:#ABB2BF;"> CURRENT </span><span style="color:#C678DD;">ROW</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> CustRunningTotal,</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    -- 所有订单总金额</span></span>
<span class="line"><span style="color:#56B6C2;">    SUM</span><span style="color:#ABB2BF;">(Amount) </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">() </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> GrandTotal,</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    -- 当前金额占比</span></span>
<span class="line"><span style="color:#56B6C2;">    CAST</span><span style="color:#ABB2BF;">(Amount </span><span style="color:#C678DD;">AS</span><span style="color:#C678DD;"> FLOAT</span><span style="color:#ABB2BF;">) / </span><span style="color:#56B6C2;">SUM</span><span style="color:#ABB2BF;">(Amount) </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">() * </span><span style="color:#D19A66;">100</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> PctOfTotal</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Orders</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> OrderDate;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-1-frame-规范" tabindex="-1"><a class="header-anchor" href="#_3-1-frame-规范"><span>3.1 Frame 规范</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- ROWS vs RANGE 的区别</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> OrderDate, Amount,</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    -- ROWS：物理行数</span></span>
<span class="line"><span style="color:#56B6C2;">    SUM</span><span style="color:#ABB2BF;">(Amount) </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> OrderDate</span></span>
<span class="line"><span style="color:#C678DD;">        ROWS</span><span style="color:#C678DD;"> BETWEEN</span><span style="color:#D19A66;"> 1</span><span style="color:#C678DD;"> PRECEDING</span><span style="color:#C678DD;"> AND</span><span style="color:#D19A66;"> 1</span><span style="color:#C678DD;"> FOLLOWING</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> RowsFrame,</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    -- RANGE：逻辑范围（同值视为一组）</span></span>
<span class="line"><span style="color:#56B6C2;">    SUM</span><span style="color:#ABB2BF;">(Amount) </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> OrderDate</span></span>
<span class="line"><span style="color:#C678DD;">        RANGE</span><span style="color:#C678DD;"> BETWEEN</span><span style="color:#C678DD;"> UNBOUNDED</span><span style="color:#C678DD;"> PRECEDING</span><span style="color:#C678DD;"> AND</span><span style="color:#ABB2BF;"> CURRENT </span><span style="color:#C678DD;">ROW</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> RangeFrame</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Orders;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><table><thead><tr><th>Frame 规范</th><th>含义</th></tr></thead><tbody><tr><td><code>ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW</code></td><td>从第一行到当前行（累计）</td></tr><tr><td><code>ROWS BETWEEN 1 PRECEDING AND 1 FOLLOWING</code></td><td>当前行的前1行到后1行</td></tr><tr><td><code>ROWS BETWEEN 7 PRECEDING AND CURRENT ROW</code></td><td>最近8行（移动窗口）</td></tr><tr><td><code>RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW</code></td><td>默认值，同值行一起计算</td></tr></tbody></table><div class="hint-container warning"><p class="hint-container-title">ROWS vs RANGE 性能差异</p><ul><li><strong>ROWS</strong>：基于物理行号，可以用优化器的高效算法</li><li><strong>RANGE</strong>：基于逻辑值，当 ORDER BY 列有重复值时，同值行一起计算，可能触发 Sort + Table Spool，性能差</li><li><strong>建议</strong>：如果不需要 RANGE 语义，优先使用 ROWS</li></ul></div><hr><h2 id="四、偏移函数" tabindex="-1"><a class="header-anchor" href="#四、偏移函数"><span>四、偏移函数</span></a></h2><h3 id="_4-1-lag-lead" tabindex="-1"><a class="header-anchor" href="#_4-1-lag-lead"><span>4.1 LAG / LEAD</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 同环比分析</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span></span>
<span class="line"><span style="color:#ABB2BF;">    OrderDate,</span></span>
<span class="line"><span style="color:#ABB2BF;">    Amount,</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    -- 前一天金额</span></span>
<span class="line"><span style="color:#56B6C2;">    LAG</span><span style="color:#ABB2BF;">(Amount, </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> OrderDate) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> PrevDayAmount,</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    -- 后一天金额</span></span>
<span class="line"><span style="color:#56B6C2;">    LEAD</span><span style="color:#ABB2BF;">(Amount, </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> OrderDate) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> NextDayAmount,</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    -- 日环比增长率</span></span>
<span class="line"><span style="color:#56B6C2;">    CAST</span><span style="color:#ABB2BF;">(Amount - </span><span style="color:#56B6C2;">LAG</span><span style="color:#ABB2BF;">(Amount, </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> OrderDate) </span><span style="color:#C678DD;">AS</span><span style="color:#C678DD;"> FLOAT</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#ABB2BF;">        / </span><span style="color:#56B6C2;">NULLIF</span><span style="color:#ABB2BF;">(</span><span style="color:#56B6C2;">LAG</span><span style="color:#ABB2BF;">(Amount, </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> OrderDate), </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">) * </span><span style="color:#D19A66;">100</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> DayOverDayPct,</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    -- 上月同日金额</span></span>
<span class="line"><span style="color:#56B6C2;">    LAG</span><span style="color:#ABB2BF;">(Amount, </span><span style="color:#D19A66;">30</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> OrderDate) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> PrevMonthAmount</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> DailySales</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> OrderDate;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-2-first-value-last-value" tabindex="-1"><a class="header-anchor" href="#_4-2-first-value-last-value"><span>4.2 FIRST_VALUE / LAST_VALUE</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">SELECT</span></span>
<span class="line"><span style="color:#ABB2BF;">    Department,</span></span>
<span class="line"><span style="color:#ABB2BF;">    EmployeeId,</span></span>
<span class="line"><span style="color:#C678DD;">    Name</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    Salary,</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    -- 部门最高薪</span></span>
<span class="line"><span style="color:#56B6C2;">    FIRST_VALUE</span><span style="color:#ABB2BF;">(Salary) </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">PARTITION</span><span style="color:#C678DD;"> BY</span><span style="color:#ABB2BF;"> Department </span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> Salary </span><span style="color:#C678DD;">DESC</span></span>
<span class="line"><span style="color:#C678DD;">        ROWS</span><span style="color:#C678DD;"> BETWEEN</span><span style="color:#C678DD;"> UNBOUNDED</span><span style="color:#C678DD;"> PRECEDING</span><span style="color:#C678DD;"> AND</span><span style="color:#C678DD;"> UNBOUNDED</span><span style="color:#C678DD;"> FOLLOWING</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> DeptMaxSalary,</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    -- ⚠️ LAST_VALUE 的常见错误</span></span>
<span class="line"><span style="color:#56B6C2;">    LAST_VALUE</span><span style="color:#ABB2BF;">(Salary) </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">PARTITION</span><span style="color:#C678DD;"> BY</span><span style="color:#ABB2BF;"> Department </span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> Salary </span><span style="color:#C678DD;">DESC</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> WrongLastValue,</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    -- ✅ 正确写法：必须指定完整 Frame</span></span>
<span class="line"><span style="color:#56B6C2;">    LAST_VALUE</span><span style="color:#ABB2BF;">(Salary) </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">PARTITION</span><span style="color:#C678DD;"> BY</span><span style="color:#ABB2BF;"> Department </span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> Salary </span><span style="color:#C678DD;">DESC</span></span>
<span class="line"><span style="color:#C678DD;">        ROWS</span><span style="color:#C678DD;"> BETWEEN</span><span style="color:#C678DD;"> UNBOUNDED</span><span style="color:#C678DD;"> PRECEDING</span><span style="color:#C678DD;"> AND</span><span style="color:#C678DD;"> UNBOUNDED</span><span style="color:#C678DD;"> FOLLOWING</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> DeptMinSalary</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Employees;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container important"><p class="hint-container-title">LAST_VALUE 的陷阱</p><p><code>LAST_VALUE</code> 默认 Frame 是 <code>RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW</code>，所以 &quot;最后一个值&quot; 实际是当前行！必须显式指定 <code>ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING</code> 才能获取真正的最后一个值。</p></div><hr><h2 id="五、经典问题" tabindex="-1"><a class="header-anchor" href="#五、经典问题"><span>五、经典问题</span></a></h2><h3 id="_5-1-去重-保留每组最新记录" tabindex="-1"><a class="header-anchor" href="#_5-1-去重-保留每组最新记录"><span>5.1 去重：保留每组最新记录</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 每个客户保留最新一条订单</span></span>
<span class="line"><span style="color:#ABB2BF;">;</span><span style="color:#C678DD;">WITH</span><span style="color:#ABB2BF;"> RankedOrders </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#ABB2BF;"> *,</span></span>
<span class="line"><span style="color:#56B6C2;">        ROW_NUMBER</span><span style="color:#ABB2BF;">() </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">PARTITION</span><span style="color:#C678DD;"> BY</span><span style="color:#ABB2BF;"> CustomerId </span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> OrderDate </span><span style="color:#C678DD;">DESC</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> rn</span></span>
<span class="line"><span style="color:#C678DD;">    FROM</span><span style="color:#ABB2BF;"> Orders</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> RankedOrders </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> rn </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_5-2-gap-and-island-间隙与岛屿" tabindex="-1"><a class="header-anchor" href="#_5-2-gap-and-island-间隙与岛屿"><span>5.2 Gap-and-Island（间隙与岛屿）</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 找出用户连续登录的天数段</span></span>
<span class="line"><span style="color:#ABB2BF;">;</span><span style="color:#C678DD;">WITH</span><span style="color:#ABB2BF;"> DailyLogins </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#C678DD;">    SELECT DISTINCT</span><span style="color:#ABB2BF;"> UserId, </span><span style="color:#56B6C2;">CAST</span><span style="color:#ABB2BF;">(LoginTime </span><span style="color:#C678DD;">AS</span><span style="color:#C678DD;"> DATE</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> LoginDate</span></span>
<span class="line"><span style="color:#C678DD;">    FROM</span><span style="color:#ABB2BF;"> UserLogins</span></span>
<span class="line"><span style="color:#ABB2BF;">),</span></span>
<span class="line"><span style="color:#ABB2BF;">Grouped </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#ABB2BF;"> UserId, LoginDate,</span></span>
<span class="line"><span style="color:#56B6C2;">        DATEADD</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">DAY</span><span style="color:#ABB2BF;">, -</span><span style="color:#56B6C2;">ROW_NUMBER</span><span style="color:#ABB2BF;">() </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">PARTITION</span><span style="color:#C678DD;"> BY</span><span style="color:#ABB2BF;"> UserId </span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> LoginDate), LoginDate) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> Grp</span></span>
<span class="line"><span style="color:#C678DD;">    FROM</span><span style="color:#ABB2BF;"> DailyLogins</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> UserId,</span></span>
<span class="line"><span style="color:#56B6C2;">    MIN</span><span style="color:#ABB2BF;">(LoginDate) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> StartDate,</span></span>
<span class="line"><span style="color:#56B6C2;">    MAX</span><span style="color:#ABB2BF;">(LoginDate) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> EndDate,</span></span>
<span class="line"><span style="color:#56B6C2;">    DATEDIFF</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">DAY</span><span style="color:#ABB2BF;">, </span><span style="color:#56B6C2;">MIN</span><span style="color:#ABB2BF;">(LoginDate), </span><span style="color:#56B6C2;">MAX</span><span style="color:#ABB2BF;">(LoginDate)) + </span><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> ConsecutiveDays</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Grouped</span></span>
<span class="line"><span style="color:#C678DD;">GROUP BY</span><span style="color:#ABB2BF;"> UserId, Grp</span></span>
<span class="line"><span style="color:#C678DD;">HAVING</span><span style="color:#56B6C2;"> DATEDIFF</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">DAY</span><span style="color:#ABB2BF;">, </span><span style="color:#56B6C2;">MIN</span><span style="color:#ABB2BF;">(LoginDate), </span><span style="color:#56B6C2;">MAX</span><span style="color:#ABB2BF;">(LoginDate)) + </span><span style="color:#D19A66;">1</span><span style="color:#56B6C2;"> &gt;=</span><span style="color:#D19A66;"> 3</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> ConsecutiveDays </span><span style="color:#C678DD;">DESC</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div>`,25),o(g,{code:`eJwrycxNzcnMS+VSAIKSzJKcVAX3xALdxLwUXc/iHCCl8LRv/vMJbWD54tTkksz8PIXnU1Y869juCBYDAcNnczoMn01fqmCl4JOfnpnnkliSqmALF9ZRKMqzNdRRcC8qsDU0Agoag0RRdBth1w0SBus2wqvbGLtukDBYtzFe3YYGOJwOEgfrN4HqBwqaYejG5XG4z02x6IaF5NNNs59u3G+IEZJ1UC+92D/v+e61xk+XrFTQQPWCJhZzjDD9VQdzH8QkI4RJUOdocgEA/PHHsw==`}),l[11]||=r(`<h3 id="_5-3-top-n-per-group" tabindex="-1"><a class="header-anchor" href="#_5-3-top-n-per-group"><span>5.3 Top-N per Group</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 每个部门工资前3名的员工</span></span>
<span class="line"><span style="color:#ABB2BF;">;</span><span style="color:#C678DD;">WITH</span><span style="color:#ABB2BF;"> RankedSalaries </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#ABB2BF;"> *,</span></span>
<span class="line"><span style="color:#56B6C2;">        DENSE_RANK</span><span style="color:#ABB2BF;">() </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">PARTITION</span><span style="color:#C678DD;"> BY</span><span style="color:#ABB2BF;"> Department </span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> Salary </span><span style="color:#C678DD;">DESC</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> drnk</span></span>
<span class="line"><span style="color:#C678DD;">    FROM</span><span style="color:#ABB2BF;"> Employees</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> RankedSalaries </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> drnk </span><span style="color:#56B6C2;">&lt;=</span><span style="color:#D19A66;"> 3</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="六、移动平均与累计统计" tabindex="-1"><a class="header-anchor" href="#六、移动平均与累计统计"><span>六、移动平均与累计统计</span></a></h2><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 7日移动平均 + 月累计</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span></span>
<span class="line"><span style="color:#ABB2BF;">    OrderDate,</span></span>
<span class="line"><span style="color:#ABB2BF;">    Amount,</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    -- 7日移动平均</span></span>
<span class="line"><span style="color:#56B6C2;">    AVG</span><span style="color:#ABB2BF;">(Amount) </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> OrderDate</span></span>
<span class="line"><span style="color:#C678DD;">        ROWS</span><span style="color:#C678DD;"> BETWEEN</span><span style="color:#D19A66;"> 6</span><span style="color:#C678DD;"> PRECEDING</span><span style="color:#C678DD;"> AND</span><span style="color:#ABB2BF;"> CURRENT </span><span style="color:#C678DD;">ROW</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> MovingAvg7,</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    -- 30日移动平均</span></span>
<span class="line"><span style="color:#56B6C2;">    AVG</span><span style="color:#ABB2BF;">(Amount) </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> OrderDate</span></span>
<span class="line"><span style="color:#C678DD;">        ROWS</span><span style="color:#C678DD;"> BETWEEN</span><span style="color:#D19A66;"> 29</span><span style="color:#C678DD;"> PRECEDING</span><span style="color:#C678DD;"> AND</span><span style="color:#ABB2BF;"> CURRENT </span><span style="color:#C678DD;">ROW</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> MovingAvg30,</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    -- 月累计</span></span>
<span class="line"><span style="color:#56B6C2;">    SUM</span><span style="color:#ABB2BF;">(Amount) </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">PARTITION</span><span style="color:#C678DD;"> BY</span><span style="color:#56B6C2;"> YEAR</span><span style="color:#ABB2BF;">(OrderDate), </span><span style="color:#56B6C2;">MONTH</span><span style="color:#ABB2BF;">(OrderDate)</span></span>
<span class="line"><span style="color:#C678DD;">        ORDER BY</span><span style="color:#ABB2BF;"> OrderDate</span></span>
<span class="line"><span style="color:#C678DD;">        ROWS</span><span style="color:#C678DD;"> BETWEEN</span><span style="color:#C678DD;"> UNBOUNDED</span><span style="color:#C678DD;"> PRECEDING</span><span style="color:#C678DD;"> AND</span><span style="color:#ABB2BF;"> CURRENT </span><span style="color:#C678DD;">ROW</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> MonthRunningTotal</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> DailySales</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> OrderDate;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="七、年同比对比报表" tabindex="-1"><a class="header-anchor" href="#七、年同比对比报表"><span>七、年同比对比报表</span></a></h2><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 年度销售同比分析</span></span>
<span class="line"><span style="color:#ABB2BF;">;</span><span style="color:#C678DD;">WITH</span><span style="color:#ABB2BF;"> YearlySales </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span></span>
<span class="line"><span style="color:#56B6C2;">        YEAR</span><span style="color:#ABB2BF;">(OrderDate) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> SalesYear,</span></span>
<span class="line"><span style="color:#56B6C2;">        MONTH</span><span style="color:#ABB2BF;">(OrderDate) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> SalesMonth,</span></span>
<span class="line"><span style="color:#56B6C2;">        SUM</span><span style="color:#ABB2BF;">(Amount) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> MonthlyAmount</span></span>
<span class="line"><span style="color:#C678DD;">    FROM</span><span style="color:#ABB2BF;"> Orders</span></span>
<span class="line"><span style="color:#C678DD;">    GROUP BY</span><span style="color:#56B6C2;"> YEAR</span><span style="color:#ABB2BF;">(OrderDate), </span><span style="color:#56B6C2;">MONTH</span><span style="color:#ABB2BF;">(OrderDate)</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span></span>
<span class="line"><span style="color:#D19A66;">    s</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">SalesYear</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#D19A66;">    s</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">SalesMonth</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#D19A66;">    s</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">MonthlyAmount</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#D19A66;">    prev</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">MonthlyAmount</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> PrevYearAmount,</span></span>
<span class="line"><span style="color:#D19A66;">    s</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">MonthlyAmount</span><span style="color:#ABB2BF;"> - </span><span style="color:#D19A66;">prev</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">MonthlyAmount</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> YoYDiff,</span></span>
<span class="line"><span style="color:#56B6C2;">    CAST</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">s</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">MonthlyAmount</span><span style="color:#ABB2BF;"> - </span><span style="color:#D19A66;">prev</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">MonthlyAmount</span><span style="color:#C678DD;"> AS</span><span style="color:#C678DD;"> FLOAT</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#ABB2BF;">        / </span><span style="color:#56B6C2;">NULLIF</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">prev</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">MonthlyAmount</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">) * </span><span style="color:#D19A66;">100</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> YoYGrowthPct</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> YearlySales s</span></span>
<span class="line"><span style="color:#C678DD;">LEFT JOIN</span><span style="color:#ABB2BF;"> YearlySales prev</span></span>
<span class="line"><span style="color:#C678DD;">    ON</span><span style="color:#D19A66;"> s</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">SalesMonth</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> prev</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">SalesMonth</span></span>
<span class="line"><span style="color:#C678DD;">    AND</span><span style="color:#D19A66;"> prev</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">SalesYear</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> s</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">SalesYear</span><span style="color:#ABB2BF;"> - </span><span style="color:#D19A66;">1</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#D19A66;"> s</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">SalesYear</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">s</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">SalesMonth</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="八、性能优化" tabindex="-1"><a class="header-anchor" href="#八、性能优化"><span>八、性能优化</span></a></h2><h3 id="_8-1-索引策略" tabindex="-1"><a class="header-anchor" href="#_8-1-索引策略"><span>8.1 索引策略</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 窗口函数的最优索引 = PARTITION BY 列 + ORDER BY 列</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 例：OVER(PARTITION BY Department ORDER BY Salary DESC)</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> INDEX</span><span style="color:#61AFEF;"> IX_Employees_Dept_Salary</span><span style="color:#C678DD;"> ON</span><span style="color:#ABB2BF;"> Employees(Department, Salary </span><span style="color:#C678DD;">DESC</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 例：OVER(ORDER BY OrderDate)</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> INDEX</span><span style="color:#61AFEF;"> IX_Orders_OrderDate</span><span style="color:#C678DD;"> ON</span><span style="color:#ABB2BF;"> Orders(OrderDate);</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container tip"><p class="hint-container-title">窗口函数索引法则</p><p><code>PARTITION BY</code> 的列放前面，<code>ORDER BY</code> 的列放后面。这样 SQL Server 可以对每个分区做 Index Seek + 有序扫描，避免 Sort 算子。</p></div><h3 id="_8-2-避免不必要的排序" tabindex="-1"><a class="header-anchor" href="#_8-2-避免不必要的排序"><span>8.2 避免不必要的排序</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- ❌ 多个窗口函数排序不同 → 多次 Sort</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span></span>
<span class="line"><span style="color:#56B6C2;">    ROW_NUMBER</span><span style="color:#ABB2BF;">() </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> OrderDate) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> rn1,</span></span>
<span class="line"><span style="color:#56B6C2;">    ROW_NUMBER</span><span style="color:#ABB2BF;">() </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> Amount </span><span style="color:#C678DD;">DESC</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> rn2</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Orders;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 执行计划: Sort(OrderDate) + Sort(Amount DESC) 两次排序</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- ✅ 尽量让多个窗口函数共享排序</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span></span>
<span class="line"><span style="color:#56B6C2;">    ROW_NUMBER</span><span style="color:#ABB2BF;">() </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">PARTITION</span><span style="color:#C678DD;"> BY</span><span style="color:#ABB2BF;"> CustomerId </span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> OrderDate </span><span style="color:#C678DD;">DESC</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> rn1,</span></span>
<span class="line"><span style="color:#56B6C2;">    DENSE_RANK</span><span style="color:#ABB2BF;">() </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">PARTITION</span><span style="color:#C678DD;"> BY</span><span style="color:#ABB2BF;"> CustomerId </span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> OrderDate </span><span style="color:#C678DD;">DESC</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> drnk</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Orders;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 执行计划: 只需一次 Sort</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="九、面试技巧" tabindex="-1"><a class="header-anchor" href="#九、面试技巧"><span>九、面试技巧</span></a></h2><div class="hint-container tip"><p class="hint-container-title">面试高频考点</p><ol><li><strong>ROW_NUMBER vs RANK vs DENSE_RANK</strong>：相同值的处理和编号是否跳号</li><li><strong>窗口函数 vs GROUP BY</strong>：保留行 vs 压缩行</li><li><strong>ROWS vs RANGE</strong>：物理行 vs 逻辑值，ROWS 性能更好</li><li><strong>LAST_VALUE 陷阱</strong>：默认 Frame 到当前行，必须显式指定完整范围</li><li><strong>Gap-and-Island</strong>：日期减行号得到常量分组键</li><li><strong>Top-N per Group</strong>：ROW_NUMBER + PARTITION BY + WHERE rn &lt;= N</li><li><strong>移动平均</strong>：ROWS BETWEEN N PRECEDING AND CURRENT ROW</li></ol></div><div class="hint-container warning"><p class="hint-container-title">易错点</p><ul><li>&quot;窗口函数在 WHERE 之后执行&quot;——❌，窗口函数在 GROUP BY/HAVING 之后、ORDER BY 之前，不能在 WHERE 中引用窗口函数列</li><li>&quot;RANGE 和 ROWS 结果一样&quot;——不一定，ORDER BY 列有重复值时不同</li><li>&quot;PARTITION BY 可以省略&quot;——✅，省略时整表作为一个分区</li></ul></div><hr><h2 id="参考资料" tabindex="-1"><a class="header-anchor" href="#参考资料"><span>参考资料</span></a></h2>`,21),s(`ul`,null,[l[5]||=s(`li`,null,[s(`a`,{href:`https://learn.microsoft.com/en-us/sql/t-sql/queries/select-over-clause-transact-sql`,target:`_blank`,rel:`noopener noreferrer`},`OVER Clause`)],-1),l[6]||=s(`li`,null,[s(`a`,{href:`https://learn.microsoft.com/en-us/sql/t-sql/functions/window-functions-transact-sql`,target:`_blank`,rel:`noopener noreferrer`},`Window Functions (Transact-SQL)`)],-1),s(`li`,null,[o(h,{to:`/%E5%90%8E%E7%AB%AF%E5%BC%80%E5%8F%91/ASP.NET_Core/SQL%20Server%E8%BF%9B%E9%98%B6/01.%E7%AA%97%E5%8F%A3%E5%87%BD%E6%95%B0%E7%B2%BE%E9%80%9A.html`},{default:n(()=>[...l[4]||=[i(`SQL Server 进阶 · 窗口函数精通`,-1)]]),_:1})])])])}var p=c(u,[[`render`,f]]);export{l as _pageData,p as default};